public class ConfigChainTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.Map<String, String> cli = java.util.Map.of("port", "9090");
        java.util.Map<String, String> env = java.util.Map.of("port", "8080", "host", "envhost");
        java.util.Map<String, String> defaults =
                java.util.Map.of("port", "80", "host", "localhost", "mode", "prod");
        java.util.Map<String, String> none = java.util.Map.of();
        check("cli wins over env and defaults", "9090", ConfigChain.lookup("port", cli, env, defaults));
        check("env wins when cli lacks the key", "envhost", ConfigChain.lookup("host", cli, env, defaults));
        check("defaults are the last resort", "prod", ConfigChain.lookup("mode", cli, env, defaults));
        check("missing everywhere", "missing:user", ConfigChain.lookup("user", cli, env, defaults));
        check("empty cli falls through to env", "8080", ConfigChain.lookup("port", none, env, defaults));
        check("only defaults populated", "80", ConfigChain.lookup("port", none, none, defaults));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

