public class ConfigChain {

    public static String lookup(String key,
                                java.util.Map<String, String> cli,
                                java.util.Map<String, String> env,
                                java.util.Map<String, String> defaults) {
        return java.util.Optional.ofNullable(cli.get(key))
                .or(() -> java.util.Optional.ofNullable(env.get(key)))
                .or(() -> java.util.Optional.ofNullable(defaults.get(key)))
                .orElse("missing:" + key);
    }
}
